gKX(){return"\u0421\u043d\u044f\u0442\u044c \u0432\u0441\u0435 \u043e\u0442\u043c\u0435\u0442\u043a\u0438"},
gKZ(){return"\u0421\u043d\u044f\u0442\u044c \u0432\u0441\u0435 \u043e\u0442\u043c\u0435\u0442\u043a\u0438?"},
gKY(){return"\u0412\u0441\u0435 \u0442\u043e\u0432\u0430\u0440\u044b \u0441\u0442\u0430\u043d\u0443\u0442 \u043d\u0435\u0439\u0442\u0440\u0430\u043b\u044c\u043d\u044b\u043c\u0438 \u2014 \u0438 \xab\u043a \u043f\u043e\u043a\u0443\u043f\u043a\u0435\xbb, \u0438 \xab\u043a\u0443\u043f\u043b\u0435\u043d\u043e\xbb. \u0421\u0430\u043c \u0441\u043f\u0438\u0441\u043e\u043a \u043d\u0435 \u0438\u0437\u043c\u0435\u043d\u0438\u0442\u0441\u044f."},
