gOR(){return"\u041f\u043e\u043a\u0443\u043f\u0430\u043b\u0438 \u0440\u0430\u043d\u044c\u0448\u0435"},
gGN(){return"\u041d\u0435 \u043f\u043e\u043a\u0443\u043f\u0430\u0442\u044c"},
gGM(){return"\u041a \u043f\u043e\u043a\u0443\u043f\u043a\u0435"},
