KN(a){return"\xab"+a+"\xbb \u0434\u043e\u0431\u0430\u0432\u043b\u0435\u043d \u0432 \u0432\u0430\u0448\u0443 \u0431\u0430\u0437\u0443 \u2014 \u0438\u0449\u0438\u0442\u0435 \u0432 \u043f\u043e\u0434\u0441\u043a\u0430\u0437\u043a\u0430\u0445"},
gN8(){return"\u041d\u0430\u0437\u0432\u0430\u043d\u0438\u0435"},
