gOZ(){return"\u041d\u0430\u0437\u0432\u0430 \u0441\u043f\u0438\u0441\u043a\u0443"},
gFk(){return"\u0420\u0435\u0446\u0435\u043f\u0442"},
gP_(){return"\u0412\u0441\u0442\u0430\u0432\u0442\u0435 \u0442\u0435\u043a\u0441\u0442 \u0440\u0435\u0446\u0435\u043f\u0442\u0430 \u2014 \u043f\u043e \u0440\u044f\u0434\u043a\u0443 \u043d\u0430 \u0456\u043d\u0433\u0440\u0435\u0434\u0456\u0454\u043d\u0442\u2026"},
