gOX(){return"\u041d\u0435 \u0437\u043d\u0430\u0439\u0448\u043e\u0432 \u0456\u043d\u0433\u0440\u0435\u0434\u0456\u0454\u043d\u0442\u0456\u0432 \u0443 \u0442\u0435\u043a\u0441\u0442\u0456"},
gNG(){return"\u041a\u0430\u0442\u0430\u043b\u043e\u0433 Mercadona"},
gNm(){return"\u041a\u0430\u0442\u0430\u043b\u043e\u0433 Lidl"},
gKM(){return"\u0417\u0430\u0432\u0430\u043d\u0442\u0430\u0436\u0443\u044e \u043a\u0430\u0442\u0430\u043b\u043e\u0433\u2026"},
KL(a,b){return a+": \u0437\u0430\u0432\u0430\u043d\u0442\u0430\u0436\u0435\u043d\u043e "+b+" \u0442\u043e\u0432\u0430\u0440\u0456\u0432"},
gKK(){return"\u041d\u0435 \u0432\u0434\u0430\u043b\u043e\u0441\u044f \u0437\u0430\u0432\u0430\u043d\u0442\u0430\u0436\u0438\u0442\u0438 \u043a\u0430\u0442\u0430\u043b\u043e\u0433. \u041f\u0435\u0440\u0435\u0432\u0456\u0440\u0442\u0435 \u0456\u043d\u0442\u0435\u0440\u043d\u0435\u0442."},
gF8(){return"\u0426\u0456\u043d\u0430, \u20ac"},
PD(a,b){return"\u0414\u043e \u043f\u043e\u043a\u0443\u043f\u043a\u0438: "+a+" \xb7 \u2248"+b+" \u20ac"},
gGY(){return"\u0420\u0435\u0436\u0438\u043c \u043c\u0430\u0433\u0430\u0437\u0438\u043d\u0443: \u0435\u043a\u0440\u0430\u043d \u043d\u0435 \u0437\u0433\u0430\u0441\u043d\u0435"},
gGX(){return"\u0420\u0435\u0436\u0438\u043c \u043c\u0430\u0433\u0430\u0437\u0438\u043d\u0443 \u0432\u0438\u043c\u043a\u043d\u0435\u043d\u043e"},
N7(a){return"\xab"+a+"\xbb \u0432\u0438\u0434\u0430\u043b\u0435\u043d\u043e"},
gu0(){return"\u0421\u043a\u0430\u0441\u0443\u0432\u0430\u0442\u0438"},
gFe(){return"\u041a\u0456\u043b\u044c\u043a\u0456\u0441\u0442\u044c (\u043d\u0430\u043f\u0440\u0438\u043a\u043b\u0430\u0434, 2 \u043a\u0433)"},
gEQ(){return"\u041d\u043e\u0442\u0430\u0442\u043a\u0430"},
gMQ(){return"\u0406\u043a\u043e\u043d\u043a\u0430"},
gKO(){return"\u041a\u0430\u0442\u0435\u0433\u043e\u0440\u0456\u044f"},
gEM(){return"\u041d\u043e\u0432\u0430 \u043a\u0430\u0442\u0435\u0433\u043e\u0440\u0456\u044f\u2026"},
gKP(){return"\u041d\u0430\u0437\u0432\u0430 \u043a\u0430\u0442\u0435\u0433\u043e\u0440\u0456\u0457"},
gDs(){return"\u0412\u0438\u0434\u0430\u043b\u0438\u0442\u0438 \u0441\u043f\u0438\u0441\u043e\u043a?"},
LG(a){return"\xab"+a+"\xbb \u0456 \u0432\u0441\u0456 \u0439\u043e\u0433\u043e \u0442\u043e\u0432\u0430\u0440\u0438 \u0431\u0443\u0434\u0435 \u0432\u0438\u0434\u0430\u043b\u0435\u043d\u043e."},
gDd(){return"\u0421\u043a\u043e\u043f\u0456\u044e\u0432\u0430\u0442\u0438 \u043f\u043e\u0441\u0438\u043b\u0430\u043d\u043d\u044f"},
gDc(){return"\u0421\u043a\u043e\u043f\u0456\u044e\u0432\u0430\u0442\u0438 \u043a\u043e\u0434"},
