GH(a){return"\u0421\u0445\u043e\u0436\u0438\u0439 \u0442\u043e\u0432\u0430\u0440: "+a},
gzP(){return"\u0417\u0432\u0438\u0447\u043d\u0438\u0439 \u043a\u043e\u0448\u0438\u043a"},
gPP(){return"\u0422\u043e\u0432\u0430\u0440\u0438 \u0437 \u0432\u0430\u0448\u0438\u0445 \u043e\u0441\u0442\u0430\u043d\u043d\u0456\u0445 \u043f\u043e\u0445\u043e\u0434\u0456\u0432. \u0417\u043d\u0456\u043c\u0456\u0442\u044c \u0437\u0430\u0439\u0432\u0435 \u2014 \u0456 \u043f\u043e\u0437\u043d\u0430\u0447\u0442\u0435 \u0432\u0441\u0435 \u0440\u0430\u0437\u043e\u043c."},
gPR(){return"\u041f\u043e\u043a\u0438 \u0437\u0430\u043c\u0430\u043b\u043e \u0456\u0441\u0442\u043e\u0440\u0456\u0457. \u0417\u0430\u0432\u0435\u0440\u0448\u0456\u0442\u044c \u0445\u043e\u0447\u0430 \u0431 \u0434\u0432\u0430 \u043f\u043e\u0445\u043e\u0434\u0438 \u043a\u043d\u043e\u043f\u043a\u043e\u044e \xab\u041d\u043e\u0432\u0438\u0439 \u043f\u043e\u0445\u0456\u0434\xbb \u2014 \u0456 \u0442\u0443\u0442 \u0437\u2019\u044f\u0432\u0438\u0442\u044c\u0441\u044f \u0432\u0430\u0448 \u0437\u0432\u0438\u0447\u043d\u0438\u0439 \u043a\u043e\u0448\u0438\u043a."},
PS(a,b){return""+a+" \u0437 "+b},
PQ(a){return"\u041f\u043e\u0437\u043d\u0430\u0447\u0438\u0442\u0438 ("+a+")"},
gAd(){return"\u0421\u043a\u0430\u043d\u0443\u0432\u0430\u0442\u0438 \u0448\u0442\u0440\u0438\u0445-\u043a\u043e\u0434"},
gGa(){return"\u041a\u0430\u043c\u0435\u0440\u0430 \u043d\u0435\u0434\u043e\u0441\u0442\u0443\u043f\u043d\u0430.\n\u0412\u0432\u0435\u0434\u0456\u0442\u044c \u043a\u043e\u0434 \u0437 \u0443\u043f\u0430\u043a\u043e\u0432\u043a\u0438 \u0432\u0440\u0443\u0447\u043d\u0443 \u0432 \u043f\u043e\u043b\u0456 \u043d\u0438\u0436\u0447\u0435."},
